contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(uint256 amount) public {
        require(true);

        uint256 beforeTotalSupply = c.totalSupply(); if (__ESBMC_reverted()) return;
        uint256 beforeTotalDistributed = c.totalDistributed(); if (__ESBMC_reverted()) return;

        bool reverted;
        c.burn(amount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint256 afterTotalSupply = c.totalSupply(); if (__ESBMC_reverted()) return;
        uint256 afterTotalDistributed = c.totalDistributed(); if (__ESBMC_reverted()) return;

        assert(
            reverted
                || (afterTotalSupply == beforeTotalSupply - amount
                    && afterTotalDistributed == beforeTotalDistributed - amount)
        );
    }
}

