pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {NewIntelTechMedia} from "../src/NewIntelTechMedia.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    NewIntelTechMedia c;

    function setUp() public {
        c = new NewIntelTechMedia();
    }

    function _run(uint256 amount) internal {
        vm.assume(true);
        uint256 beforeTotalSupply;
        try c.totalSupply() returns (uint256 __r) { beforeTotalSupply = __r; } catch { return; }
        uint256 beforeTotalDistributed;
        try c.totalDistributed() returns (uint256 __r) { beforeTotalDistributed = __r; } catch { return; }
        bool reverted;
        try c.burn(amount) {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 afterTotalSupply;
        try c.totalSupply() returns (uint256 __r) { afterTotalSupply = __r; } catch { return; }
        uint256 afterTotalDistributed;
        try c.totalDistributed() returns (uint256 __r) { afterTotalDistributed = __r; } catch { return; }
        assertTrue(reverted
                || (afterTotalSupply == beforeTotalSupply - amount
                    && afterTotalDistributed == beforeTotalDistributed - amount));
    }

    function testFuzz_run(uint256 amount) public {
        _run(amount);
    }

    receive() external payable {}
}
